<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\DcrInitialAccessTokenRef;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Service\Visibility\DcrInitialAccessTokenVisibilityService;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Gateway\DcrInitialAccessTokenQueryRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class DcrInitialAccessTokenRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly DcrInitialAccessTokenVisibilityService $visibility,
        private readonly DcrInitialAccessTokenQueryRepositoryGateway $reader
    ) {
    }

    public function allowRetrieve(?DcrInitialAccessTokenRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Dcr initial access token");
        $span = $this->startSpan("Check allow of retrieve usecase for Dcr initial access token");
        try {
            $result = $this->dispatcher->dispatch(new DcrInitialAccessTokenRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?DcrInitialAccessTokenRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Dcr initial access token");
        $span = $this->startSpan("Check hidden fields usecase for Dcr initial access token");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): DcrInitialAccessTokenRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Dcr initial access token");
        $span = $this->startSpan("Run retrieve usecase for Dcr initial access token");
        try {
            $ref = new DcrInitialAccessTokenRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Dcr initial access token');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new DcrInitialAccessTokenRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
